@startuml

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class PickupRequest {
  + StreetAddress : string
  + Description : string
  + PickupTime : time
}

class Vehicle {
  + StorageSpace : float
}

class VolunteerDriver {
  + AvailableDays : string[]
}

class Route {
  + Date : date
}

class Article {
  + Description : string
  + Dimensions : string
  + Weight : float
}

class Category {
  + Name : string
}

class H2SLocation {
}

class DistributionCenter extends H2SLocation {}

class FoodBank {
}

class Client {
  + HomeAddress : string
  + NeededCategories : string[]
}

class H2SEmployee {
}

class Delivery {
}

Resident "1" -- "*" PickupRequest : schedules
PickupRequest "1" -- "1" Article : involves
PickupRequest "*" -- "1" Vehicle : assigned to
PickupRequest "*" -- "1" Route : part of
Route "1" -- "1" Vehicle : for
Route "1" -- "1" VolunteerDriver : driven by
Article "*" -- "1" Category : belongs to
Article "1" -- "1" DistributionCenter : dropped off at
Article "1" -- "1" FoodBank : dropped off at
Article "1" -- "1" H2SEmployee : examined by
Client "1" -- "*" Delivery : receives
Delivery "1" -- "1" Article : contains
Delivery "1" -- "1" VolunteerDriver : performed by
Client "1" -- "0..1" H2SEmployee : contacted by
H2SEmployee "1" -- "*" Delivery : arranges
H2SEmployee "1" -- "*" Article : categorizes
H2SEmployee "1" -- "*" Article : examines

@enduml

